// The settings page's copy for Acme: the sections, the profile fields and the notification switches.
export const settingsContent = {
	nav: [
		{ label: 'Profile', href: '#profile', current: true },
		{ label: 'Team', href: '#team' },
		{ label: 'Billing', href: '#billing' },
		{ label: 'API keys', href: '#keys' },
	],
	title: 'Settings',
	profile: { title: 'Profile', name: { label: 'Name', value: 'Alex Kim' }, email: { label: 'Email', value: 'alex@acme.com' } },
	notifications: {
		title: 'Notifications',
		items: [
			{ label: 'Weekly summary', description: 'What changed across the brands you track, every Monday.', on: true },
			{ label: 'Launch alerts', description: 'An email the day a tracked brand ships a new ad.', on: false },
		],
	},
	save: 'Save changes',
}
export type SettingsContent = typeof settingsContent

/** The settings page's sections in order; pass `sections` to reorder them or leave some out. */
export const settingsSections = ['profile', 'notifications', 'save'] as const
export type SettingsSection = (typeof settingsSections)[number]

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

